function_drift AS (
 SELECT e.s||'.'||e.n||'('||e.a||')' AS object FROM ef e
 LEFT JOIN pg_namespace n ON n.nspname=e.s LEFT JOIN pg_proc p ON p.pronamespace=n.oid AND p.proname=e.n AND pg_get_function_identity_arguments(p.oid)=e.a
 WHERE p.oid IS NULL OR md5(replace(pg_get_functiondef(p.oid),chr(13),''))<>e.h OR pg_get_userbyid(p.proowner)<>e.o OR p.proacl::text IS DISTINCT FROM e.acl
),policy_drift AS (
 SELECT e.s||'.'||e.t||':'||e.n AS object FROM ep e LEFT JOIN pg_policies p ON p.schemaname=e.s AND p.tablename=e.t AND p.policyname=e.n
 WHERE p.policyname IS NULL OR p.cmd<>e.cmd OR p.permissive<>e.permissive OR to_jsonb(p.roles)<>e.roles::jsonb OR p.qual IS DISTINCT FROM e.qual OR p.with_check IS DISTINCT FROM e.chk
),table_drift AS (
 SELECT e.s||'.'||e.n AS object FROM et e LEFT JOIN pg_namespace n ON n.nspname=e.s LEFT JOIN pg_class t ON t.relnamespace=n.oid AND t.relname=e.n
 WHERE t.oid IS NULL OR pg_get_userbyid(t.relowner)<>e.o OR t.relrowsecurity<>e.rls::boolean OR t.relforcerowsecurity<>e.force_rls::boolean OR coalesce(to_jsonb(t.relacl),'null'::jsonb)<>e.acl::jsonb OR (SELECT count(*) FROM pg_attribute a WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped)<>e.cols::integer
),column_drift AS (
 SELECT e.s||'.'||e.t||'.'||e.n AS object FROM ec e LEFT JOIN pg_namespace n ON n.nspname=e.s LEFT JOIN pg_class t ON t.relnamespace=n.oid AND t.relname=e.t
 LEFT JOIN pg_attribute a ON a.attrelid=t.oid AND a.attname=e.n AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=t.oid AND d.adnum=a.attnum
 WHERE a.attname IS NULL OR format_type(a.atttypid,a.atttypmod)<>e.typ OR a.attnotnull<>e.nn::boolean OR pg_get_expr(d.adbin,d.adrelid) IS DISTINCT FROM e.def OR a.attidentity::text<>e.ident OR a.attgenerated::text<>e.gen OR coalesce(to_jsonb(a.attacl),'null'::jsonb)<>e.acl::jsonb
)
SELECT jsonb_build_object('sourceFunctions',34,'sourcePolicies',113,'sourceTables',28,'sourceColumns',247,
'functionDrift',coalesce((SELECT jsonb_agg(object) FROM function_drift),'[]'::jsonb),'policyDrift',coalesce((SELECT jsonb_agg(object) FROM policy_drift),'[]'::jsonb),
'tableDrift',coalesce((SELECT jsonb_agg(object) FROM table_drift),'[]'::jsonb),'columnDrift',coalesce((SELECT jsonb_agg(object) FROM column_drift),'[]'::jsonb),
'orphanProjects',(SELECT count(*) FROM public.studio_projects p LEFT JOIN public.profiles u ON u.id=p.owner_id WHERE u.id IS NULL),
'orphanCards',(SELECT count(*) FROM public.studio_cards c LEFT JOIN public.studio_projects p ON p.id=c.project_id WHERE p.id IS NULL),
'authAccounts',(SELECT count(*) FROM auth.users),'profiles',(SELECT count(*) FROM public.profiles),'projects',(SELECT count(*) FROM public.studio_projects),'cards',(SELECT count(*) FROM public.studio_cards),
'studioAccessRows',(SELECT count(*) FROM public.studio_access),'programmeEnrolments',(SELECT count(*) FROM public.studio_programme_enrolments),
'privateJournalBucket',(SELECT NOT public FROM storage.buckets WHERE id='studio-journal-photos'),
'executorRestricted',(SELECT NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolinherit FROM pg_roles WHERE rolname='dcs_service_executor')) AS gate;
